//! Embedded images: monster portraits and small icons.
//!
//! Images are only *bytes* here; egui decodes one when it is first shown
//! and keeps it as a texture, so memory grows only with what is displayed.

// Generated by build.rs: `pub static SPRITES: &[(&str, &[u8])]`, sorted.
include!(concat!(env!("OUT_DIR"), "/sprites.rs"));

/// PNG bytes of a monster portrait (75×75), by monster identifier.
pub fn sprite(identifier: &str) -> Option<&'static [u8]> {
    // The table is sorted by build.rs: binary search, ~10 steps for 527.
    SPRITES
        .binary_search_by_key(&identifier, |&(id, _)| id)
        .ok()
        .map(|i| SPRITES[i].1)
}

/// Small icons from `data/Misc/` (24×24), by name: family identifiers
/// ("slime", …, "boss") and lowercase English season / weather names
/// ("spring", "sun", …), which are also the file names.
static ICONS: &[(&str, &[u8])] = &[
    ("slime", include_bytes!("../../../data/Misc/slime.png")),
    ("dragon", include_bytes!("../../../data/Misc/dragon.png")),
    ("nature", include_bytes!("../../../data/Misc/nature.png")),
    ("beast", include_bytes!("../../../data/Misc/beast.png")),
    (
        "material",
        include_bytes!("../../../data/Misc/material.png"),
    ),
    ("demon", include_bytes!("../../../data/Misc/demon.png")),
    ("undead", include_bytes!("../../../data/Misc/undead.png")),
    ("boss", include_bytes!("../../../data/Misc/boss.png")),
    ("spring", include_bytes!("../../../data/Misc/spring.png")),
    ("summer", include_bytes!("../../../data/Misc/summer.png")),
    ("fall", include_bytes!("../../../data/Misc/fall.png")),
    ("winter", include_bytes!("../../../data/Misc/winter.png")),
    ("sun", include_bytes!("../../../data/Misc/sun.png")),
    (
        "precipitation",
        include_bytes!("../../../data/Misc/precipitation.png"),
    ),
];

/// PNG bytes of an icon (family, season or weather).
pub fn icon(name: &str) -> Option<&'static [u8]> {
    ICONS
        .iter()
        .find(|(n, _)| *n == name)
        .map(|(_, bytes)| *bytes)
}

#[cfg(test)]
mod tests {
    use super::*;
    use dqm3_core::{Database, FamilyId, SeasonId, WeatherId};

    #[test]
    fn every_family_season_and_weather_has_an_icon() {
        let db = Database::load().expect("embedded data is valid");
        for id in 1..=8 {
            let family = db.family(FamilyId(id)).expect("family exists");
            assert!(icon(&family.identifier).is_some(), "{}", family.identifier);
        }
        for id in 1..=4 {
            let season = db.season(SeasonId(id)).expect("season exists");
            assert!(
                icon(&season.name_en.to_lowercase()).is_some(),
                "{}",
                season.name_en
            );
        }
        for id in 1..=2 {
            let weather = db.weather(WeatherId(id)).expect("weather exists");
            assert!(
                icon(&weather.name_en.to_lowercase()).is_some(),
                "{}",
                weather.name_en
            );
        }
        assert_eq!(icon("unknown"), None);
    }

    #[test]
    fn every_real_monster_has_a_portrait() {
        let db = Database::load().expect("embedded data is valid");
        let missing: Vec<&str> = db
            .monsters()
            .iter()
            .filter(|m| !m.is_family_rule())
            .filter(|m| sprite(&m.identifier).is_none())
            .map(|m| m.identifier.as_str())
            .collect();
        assert!(missing.is_empty(), "no portrait for {missing:?}");
    }

    #[test]
    fn portraits_are_png_files() {
        let bytes = sprite("slime").expect("slime portrait");
        assert!(bytes.starts_with(b"\x89PNG"));
        assert_eq!(sprite("no-such-monster"), None);
    }
}
